package OOPS.Encapsulation;public class Bank {    private int account_number;    private int balance;    private int amount;    public void deposit(int amount){        if(amount<=0){            System.out.println("invalid transaction");        }        else{            this.balance=this.balance+amount;            System.out.println("deposited_amount "+amount);        }    }    public int withdraw(int amount){        if(amount<0 || amount>balance){            System.out.println("invalid transaction");        }        else{            this.balance=this.balance-amount;            System.out.println("withdraw_amount "+amount);        }        return this.balance;    }    public static void main(String[] args) {        Bank b1=new Bank();        b1.deposit(100);        b1.deposit(100);        System.out.println(b1.withdraw(300));    }}